// Shared QA/test-traffic classifier. GENERATED by ~/ytwork/_brand-beacon/gen-qa-traffic.py on 5950: do not edit a copy,
// edit the template/private list there and re-run (one config place; copies in MYO, the 4 brand sites and VCF).
// Builder, 30 Oct 2026 (Chief via Constraint Bot review). Works in Cloudflare Workers and Node 18+ (WebCrypto).
//   crawler -> class-only beacon; no page or click key
//   test    -> counted only on the site's <prefix>-test:* keys, never on real keys:
//              src / client_reference_id starting test or qa (any case), OR a QA tool user agent
//              (headless Chrome, Lighthouse, Playwright, Puppeteer, WebPageTest, curl, wget, script HTTP clients),
//              OR the visitor IP is one of our machines (salted hashes only; raw IPs stay in qa-ips.private.json).
//   real    -> everything else.
export const TEST_SRC = /^(test|qa)/i;
export const CRAWLER_UA = /bot|crawl|spider|slurp|facebookexternalhit|bingpreview|embedly|whatsapp|telegram/i;
export const QA_UA = /headlesschrome|lighthouse|playwright|puppeteer|ptst|curl\/|wget\/|python-requests|python-urllib|aiohttp|httpx|node-fetch|undici|axios\/|go-http-client|okhttp|^node$|builder-testtag|grokbot-qa/i;
const SALT = "qa-ip-v1|";
const QA_IP_HASHES = new Set(["050e13358972cb52", "2b963e4721864c94", "d9360d0eee46e303"]);

export const cleanSrc = (v) => String(v || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 200);
export const isTestSrc = (v) => TEST_SRC.test(String(v || ""));
export const isCrawlerUa = (ua) => CRAWLER_UA.test(String(ua || ""));
export const isQaUa = (ua) => QA_UA.test(String(ua || ""));

// IPv4 as-is; IPv6 reduced to its /64 ("2001:0db8:0005:000a::/64"). Returns "" for anything else.
export function ipKey(ip) {
  const s = String(ip || "").trim().toLowerCase();
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(s)) return s.split(".").every((o) => +o <= 255) ? s.split(".").map((o) => String(+o)).join(".") : "";
  if (!/^[0-9a-f:]+$/.test(s) || !s.includes(":")) return "";
  const [head, tail = ""] = s.split("::");
  const h = head ? head.split(":") : [], t = tail ? tail.split(":") : [];
  if (!s.includes("::") && h.length !== 8) return "";
  const full = [...h, ...Array(8 - h.length - t.length).fill("0"), ...t];
  if (full.length !== 8 || full.some((g) => g.length > 4)) return "";
  return full.slice(0, 4).map((g) => g.padStart(4, "0")).join(":") + "::/64";
}

async function sha16(text) {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(d)].slice(0, 8).map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function isQaIp(ip) {
  const k = ipKey(ip);
  return k ? QA_IP_HASHES.has(await sha16(SALT + k)) : false;
}

/** "crawler" | "test" | "real". ip = the visitor's own IP (cf-connecting-ip / first x-forwarded-for). */
export async function classify({ src, clientReferenceId, ua, ip } = {}) {
  if (isCrawlerUa(ua)) return "crawler";
  if (isTestSrc(src) || isTestSrc(clientReferenceId) || isQaUa(ua) || (await isQaIp(ip))) return "test";
  return "real";
}

/** Map real keys to the site's test bucket: "<p>/page" -> "<p>-test:view/page", "<p>-click:/x" -> "<p>-test:click:/x". */
export function testKey(prefix, key) {
  let k = key;
  if (k.startsWith(prefix + "/")) k = prefix + "-test:view" + k.slice(prefix.length);
  else if (k.startsWith(prefix + "-")) k = prefix + "-test:" + k.slice(prefix.length + 1);
  else if (!k.startsWith(prefix + "-test:")) k = prefix + "-test:" + k;
  return k.slice(0, 64);
}

/** Pure UA evidence classifier. QA routing remains a separate decision. */
export function classifyUA(request) {
  const h = request.headers;
  const ua = h.get("user-agent") || "";
  if (/facebookexternalhit|facebot|twitterbot|slackbot|discordbot|linkedinbot|whatsapp|telegrambot|skypeuripreview|pinterestbot|redditbot|embedly|iframely|vkshare|mastodon|bluesky|cardyb|google-pagerenderer|snap(?:chat)?[ /_-]*url[ /_-]*preview|microsoft[ /_-]*preview/i.test(ua) || (/applebot/i.test(ua) && !/safari/i.test(ua))) return "link-preview";
  if (!ua.trim() || /bot|crawl|spider|scan|monitor|preview|fetch|archiver|slurp|chatgpt-user|claude-user|meta-externalagent|uptimerobot|pingdom|statuscake|better[ -]?stack|site24x7/i.test(ua.replace(/node-fetch/ig, "node-client"))) return "bot";
  if (/headlesschrome|phantomjs|puppeteer|playwright|lighthouse|selenium|curl|wget|python-requests|python-httpx|aiohttp|go-http-client|node-fetch|undici|axios|okhttp|java\/|libwww|scrapy|httpclient/i.test(ua)) return "headless";
  const chrome = ua.match(/Chrome\/(\d+)/i);
  const language = h.get("accept-language");
  const mode = h.get("sec-fetch-mode");
  if ((!language && !mode) || (chrome && ((mode === "navigate" && !h.get("sec-ch-ua")) || +chrome[1] < 100))) return "suspect";
  if (/Mozilla\/5\.0/i.test(ua) && /AppleWebKit\/|Gecko\/|Trident\//i.test(ua) && language) return "browser";
  // Unrecognised clients are not evidence of a human browser.
  return "suspect";
}

/** Add exactly one class key; keep QA keys unchanged and crawler page keys absent. */
export function uaKeys(request, keys, prefix, traffic) {
  const uaClass = classifyUA(request);
  if (traffic === "crawler") return [prefix + "-ua:" + (uaClass === "link-preview" ? uaClass : "bot")];
  if (traffic === "test") return keys;
  return [...keys, prefix + "-ua:" + uaClass];
}
